// Storage contract. CONTRACT (Phase 0): the JSON-file store (Phase 3) and the Supabase store
// (Phase 4) both implement Repository exactly. The web and mobile apps only ever talk to this.
//
// Rules every implementation follows:
// - Methods never throw for "not found": they return null / [] instead. They throw RepoError for
//   rule violations (bad input, conflicts, forbidden).
// - Ids are generated by the store (crypto.randomUUID()). Timestamps use the injected clock.
// - ApplicantProfile.sensitive and document bytes are encrypted at rest; reads return plaintext.
// - Returned objects are copies: mutating them never changes stored data.

import type {
  AccessibilityInfo,
  Alert,
  AlertEvent,
  AlertEventDraft,
  ApplicantProfile,
  Application,
  ApplicationDocument,
  ApplicationMember,
  ApplicationStatus,
  Building,
  FeeQuote,
  FloorPlan,
  Group,
  GroupMember,
  ID,
  ISODate,
  Landlord,
  Landmark,
  Listing,
  Major,
  Photo,
  Property,
  Review,
  Save,
  Section,
  ShortlistItem,
  Swipe,
  User,
  UserSchedule,
  Vote,
  WalkTime,
} from '@homed/core';

export type RepoErrorCode = 'invalid' | 'conflict' | 'forbidden' | 'not_found';

export class RepoError extends Error {
  constructor(
    public readonly code: RepoErrorCode,
    message: string,
  ) {
    super(message);
    this.name = 'RepoError';
  }
}

export interface CatalogRepo {
  /** Every floor plan joined with its property, photos and accessibility info. */
  listListings(): Promise<Listing[]>;
  getListing(floorPlanId: ID): Promise<Listing | null>;
  getProperty(propertyId: ID): Promise<Property | null>;
  getPropertyBySlug(slug: string): Promise<Property | null>;
  listPropertyListings(propertyId: ID): Promise<Listing[]>;
  listBuildings(): Promise<Building[]>;
  listLandmarks(): Promise<Landmark[]>;
  listMajors(): Promise<Major[]>;
  listSections(term?: string): Promise<Section[]>;
  /** All rows, or only rows for these properties. */
  listWalkTimes(propertyIds?: ID[]): Promise<WalkTime[]>;
  /** Student swipe rating of a real photo, 1-5. Updates Photo.looksRating / ratingCount. One rating per user per photo (re-rating replaces). */
  ratePhoto(userId: ID, photoId: ID, rating: number): Promise<Photo>;
}

export interface NewUser {
  email: string;
  name: string;
  role: User['role'];
}

export interface UserRepo {
  getUser(id: ID): Promise<User | null>;
  getUserByEmail(email: string): Promise<User | null>;
  /** Throws RepoError('invalid') when a student email is not @virginia.edu, ('conflict') when the email exists. Weights default to DEFAULT_WEIGHTS. */
  createUser(input: NewUser): Promise<User>;
  updateUser(id: ID, patch: Partial<Omit<User, 'id' | 'email' | 'role' | 'createdAt'>>): Promise<User>;
  getSchedule(userId: ID): Promise<UserSchedule | null>;
  saveSchedule(schedule: Omit<UserSchedule, 'updatedAt'>): Promise<UserSchedule>;
}

export interface SaveRepo {
  listSaves(userId: ID): Promise<Save[]>;
  /** Idempotent. */
  addSave(userId: ID, floorPlanId: ID, note?: string): Promise<Save>;
  removeSave(userId: ID, floorPlanId: ID): Promise<void>;
  /** A right swipe also adds a solo save (no groupId) or a group shortlist item (groupId). Re-swiping replaces the earlier swipe. */
  recordSwipe(swipe: Omit<Swipe, 'createdAt'>): Promise<Swipe>;
  listSwipes(filter: { userId?: ID; groupId?: ID }): Promise<Swipe[]>;
}

export interface GroupRepo {
  /** Creator becomes the leader. */
  createGroup(ownerId: ID, name: string): Promise<Group>;
  getGroup(groupId: ID): Promise<Group | null>;
  getGroupByInviteCode(code: string): Promise<Group | null>;
  listGroupsForUser(userId: ID): Promise<Group[]>;
  listMembers(groupId: ID): Promise<GroupMember[]>;
  /** Idempotent for existing members. Max 8 members: RepoError('conflict'). */
  joinGroup(inviteCode: string, userId: ID): Promise<GroupMember>;
  /** The last leader leaving promotes the earliest-joined member; the last member leaving deletes the group. */
  leaveGroup(groupId: ID, userId: ID): Promise<void>;
  updateMember(groupId: ID, userId: ID, patch: { budgetMax?: number | null }): Promise<GroupMember>;
  listShortlist(groupId: ID): Promise<ShortlistItem[]>;
  /** Idempotent. Caller must be a member: RepoError('forbidden'). */
  addToShortlist(groupId: ID, userId: ID, floorPlanId: ID, note?: string): Promise<ShortlistItem>;
  removeFromShortlist(groupId: ID, floorPlanId: ID): Promise<void>;
  /** Replaces the user's earlier vote on that floor plan. Caller must be a member. */
  castVote(groupId: ID, userId: ID, floorPlanId: ID, value: Vote['value']): Promise<Vote>;
  listVotes(groupId: ID): Promise<Vote[]>;
}

export interface AlertRepo {
  listAlerts(userId: ID): Promise<Alert[]>;
  /** Every user's alerts, for the catalog-change diff. */
  listAllAlerts(): Promise<Alert[]>;
  createAlert(input: Omit<Alert, 'id' | 'createdAt'>): Promise<Alert>;
  deleteAlert(userId: ID, alertId: ID): Promise<void>;
  addAlertEvents(drafts: AlertEventDraft[]): Promise<AlertEvent[]>;
  /** Newest first. */
  listAlertEvents(userId: ID, opts?: { unreadOnly?: boolean }): Promise<AlertEvent[]>;
  markAlertEventsRead(userId: ID, eventIds: ID[]): Promise<void>;
}

export interface ReviewRepo {
  /** Published only, unless includeAll (moderation view). Newest first. */
  listReviews(propertyId: ID, opts?: { includeAll?: boolean }): Promise<Review[]>;
  /** Student users only (@virginia.edu); one review per user per property: RepoError('conflict'). New reviews start 'pending'. */
  createReview(input: Pick<Review, 'propertyId' | 'userId' | 'ratings' | 'text'>): Promise<Review>;
  listPendingReviews(): Promise<Review[]>;
  moderateReview(reviewId: ID, status: 'published' | 'rejected'): Promise<Review>;
  /** Landlord right to reply. */
  replyToReview(reviewId: ID, reply: string): Promise<Review>;
}

export interface NewApplicationBatch {
  leaderId: ID;
  groupId?: ID;
  /** 1-3 floor plans in preference order. */
  floorPlanIds: ID[];
  /** Roommates (not the leader) and guarantors invited on every application in the batch. */
  invitees: { kind: 'roommate' | 'guarantor'; email: string; name?: string; guarantorForEmail?: string }[];
  /** One fee quote per floor plan, same order. */
  fees: FeeQuote[];
}

export interface StoredDocumentInput {
  memberId: ID;
  filename: string;
  mime: string;
  bytes: Uint8Array;
  deleteAfter: ISODate;
}

export interface ApplicationRepo {
  getApplicantProfile(userId: ID): Promise<ApplicantProfile | null>;
  saveApplicantProfile(profile: Omit<ApplicantProfile, 'updatedAt'>): Promise<ApplicantProfile>;
  /** Creates one draft application per floor plan sharing a new batchId, ranks 1..n, a 'leader' member (done = false) plus invitee members on each. More than MAX_BATCH_SIZE: RepoError('invalid'). */
  createApplicationBatch(input: NewApplicationBatch): Promise<Application[]>;
  getApplication(applicationId: ID): Promise<Application | null>;
  listBatch(batchId: ID): Promise<Application[]>;
  /** Applications where the user is the leader or a member. */
  listApplicationsForUser(userId: ID): Promise<Application[]>;
  /** Applications to any of the landlord's properties, excluding drafts. */
  listApplicationsForLandlord(landlordId: ID): Promise<Application[]>;
  /** Enforces canTransition; appends to statusHistory; sets submittedAt / decidedAt. Illegal move: RepoError('invalid'). */
  updateApplicationStatus(applicationId: ID, to: ApplicationStatus, byUserId: ID): Promise<Application>;
  listApplicationMembers(applicationId: ID): Promise<ApplicationMember[]>;
  getMemberByInviteToken(token: string): Promise<ApplicationMember | null>;
  updateApplicationMember(memberId: ID, patch: Partial<Pick<ApplicationMember, 'userId' | 'name' | 'inviteStatus' | 'done'>>): Promise<ApplicationMember>;
  putDocument(input: StoredDocumentInput): Promise<ApplicationDocument>;
  listDocuments(memberId: ID): Promise<ApplicationDocument[]>;
  getDocumentBytes(documentId: ID): Promise<Uint8Array | null>;
  /** Deletes documents whose deleteAfter <= today. Returns how many were deleted. */
  purgeExpiredDocuments(today: ISODate): Promise<number>;
}

export interface LandlordRepo {
  getLandlord(landlordId: ID): Promise<Landlord | null>;
  getLandlordByUser(userId: ID): Promise<Landlord | null>;
  listLandlords(): Promise<Landlord[]>;
  createLandlord(input: Omit<Landlord, 'id' | 'createdAt' | 'verified'>): Promise<Landlord>;
  /** Insert (no id) or update. Self-listed properties get dataStatus 'unverified_seed' until an admin verifies. */
  upsertProperty(input: Omit<Property, 'id'> & { id?: ID }): Promise<Property>;
  upsertFloorPlan(input: Omit<FloorPlan, 'id'> & { id?: ID }): Promise<FloorPlan>;
  deleteFloorPlan(floorPlanId: ID): Promise<void>;
  upsertPhoto(input: Omit<Photo, 'id' | 'looksRating' | 'ratingCount'> & { id?: ID }): Promise<Photo>;
  deletePhoto(photoId: ID): Promise<void>;
  upsertAccessibility(info: AccessibilityInfo): Promise<AccessibilityInfo>;
  /** Weekly availability check: sets unitsAvailable and lastVerified (floor plan and its property) to `on`. */
  confirmAvailability(floorPlanId: ID, unitsAvailable: number | null, on: ISODate): Promise<FloorPlan>;
}

export interface Repository
  extends CatalogRepo,
    UserRepo,
    SaveRepo,
    GroupRepo,
    AlertRepo,
    ReviewRepo,
    ApplicationRepo,
    LandlordRepo {
  readonly backend: 'json' | 'supabase';
}

/** Injected into stores so tests control time and ids. */
export interface StoreClock {
  now(): Date;
}

export const systemClock: StoreClock = { now: () => new Date() };
